def _run_root(self, cmd):
    """Executes a command using the established root context."""
    if not self.is_root:
        return "[-] Error: Root context not established. Run 'auto_root' first.\n"
    try:
        # We use su -c if we don't have a persistent shell, 
        # but ideally auto_root would have bypassed the prompt.
        full_cmd = f"su -c '{cmd}'"
        proc = self._s.run(getattr(self._sh, 'split')(full_cmd), capture_output=True, text=True, timeout=30)
        return (proc.stdout + proc.stderr) or " \n"
    except Exception as e:
        return f"[-] Root Command Error: {e}\n"

