    @classmethod
    def UpdateReconDB(cls):
        db = cls.db
        allfiles = []
        for x in os.listdir(f"{install_location}/recon"):
            files = []
            for i in os.listdir(f"{install_location}/recon/{x}"):
                allfiles.append(f"{install_location}/recon/{x}/{i}")
                files.append(f"{install_location}/recon/{x}/{i}")
            db[x] = files
        return db, allfiles

    @classmethod
    def _reconDB(cls):
        return cls.db

